  "ui.mediaStarter.image1.title": "Editorial portrait",
  "ui.mediaStarter.image1.tag": "Portrait",
  "ui.mediaStarter.image1.prompt": "A close-up editorial portrait of a young creative director in their late 20s, soft natural light through tall studio windows, warm neutral palette (cream, taupe, soft black), shot at 85mm f/1.8 with shallow depth of field, sharp gaze straight to camera, subtle film grain, no makeup look.",
  "ui.mediaStarter.image2.title": "Product hero",
  "ui.mediaStarter.image2.tag": "E-commerce",
  "ui.mediaStarter.image2.prompt": "A premium product hero shot of a single matte ceramic coffee mug on a warm cream paper backdrop. Hard rim light from the upper-left, gentle elongated shadow stretching to the lower-right, faint steam rising from the cup. Square crop, centered composition, room above for headline copy, no props or hands in frame.",
  "ui.mediaStarter.image3.title": "Flat illustration",
  "ui.mediaStarter.image3.tag": "Illustration",
  "ui.mediaStarter.image3.prompt": "A flat vector illustration of a cozy reading nook by a rainy window — geometric shapes, restrained 5-color palette (cream, terracotta, deep teal, burnt sienna, soft black), thin 1.5px line accents, no gradients, no textures, soft drop shadows only on the foreground armchair.",
  "ui.mediaStarter.video1.title": "Product reveal",
  "ui.mediaStarter.video1.tag": "Cinematic",
  "ui.mediaStarter.video1.prompt": "A 5-second product reveal: a minimal high-end skincare bottle on a clean cream stone surface, soft side light from camera-left, slow camera push-in, subtle depth-of-field shift from the cap to the label, restrained motion, no text overlays, no people in frame.",
  "ui.mediaStarter.video2.title": "Lantern close-up",
  "ui.mediaStarter.video2.tag": "Mood",
  "ui.mediaStarter.video2.prompt": "A 6-second cinematic close-up of a young woman holding a glowing paper lantern in a misty pine forest at golden hour. Shallow depth of field on her eyes, gentle dolly-in, ambient particles drifting through the warm shaft of light, no dialogue, ambient forest sound only.",
  "ui.mediaStarter.video3.title": "Neon street drift",
  "ui.mediaStarter.video3.tag": "Action",
  "ui.mediaStarter.video3.prompt": "A 5-second street-racing tracking shot at night in a neon-lit cyberpunk Hong Kong alley. Low-angle camera following a matte-black sports car drifting around a tight corner, motion blur on the wheels, lens flares from oncoming neon signs, rain-slick asphalt reflecting the lights, no on-screen text.",
  "ui.mediaStarter.hyperframes1.title": "Magnifying glass reveal",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Make a 5-second composition with a single line of bold display text on a clean canvas. Animate a round magnifying glass that travels left to right across the line, with subtle glass refraction warping the letters underneath as it passes. Use HyperFrames html-in-canvas — capture the text DOM and run the lens shader on top via a vfx-liquid-glass-style pass. Pure CSS for the text; the glass is a WebGL layer.",
  "ui.mediaStarter.hyperframes2.title": "CRT terminal scene",
  "ui.mediaStarter.hyperframes2.tag": "Vintage VFX",
  "ui.mediaStarter.hyperframes2.prompt": "Make a CRT-screen composition: dark canvas, monospace terminal text typing `npx hyperframes init my-video`, then `claude` invoked with the prompt 'Add a CRT effect using HTML-in-canvas'. Apply a subtle convex-curvature shader, scanlines, slight chromatic aberration, and a soft phosphor glow on top of the live DOM via html-in-canvas. The terminal text stays as real CSS so it's pixel-sharp before the shader pass.",
  "ui.mediaStarter.hyperframes3.title": "Glitch breakdown",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Build a 6-second composition that displays a hero headline and a one-line subhead on a dark canvas, then breaks into a hard digital glitch — RGB channel split, horizontal displacement bands, brief frame-stutter, and a final clean reset. Capture the live DOM via html-in-canvas and run the glitch pass on top, so the type is real CSS underneath the shader.",
  "ui.mediaStarter.audio1.title": "Brand voiceover",
  "ui.mediaStarter.audio1.tag": "Speech",
  "ui.mediaStarter.audio1.prompt": "A 30-second warm-toned narrative voiceover for a product launch video — confident but conversational, mid-tempo, with a beat of pause after the brand name. Script: 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' English, neutral North American accent.",
  "ui.mediaStarter.audio2.title": "Onboarding narration",
  "ui.mediaStarter.audio2.tag": "Speech",
  "ui.mediaStarter.audio2.prompt": "A 20-second friendly onboarding narration for a mobile app's first-launch screen. Reassuring, smiling tone, slow enough to feel attentive without sounding scripted. Script: 'Welcome to Loop. Let's set up your space — three quick questions and you're in. You can change any of this later.'",
  "ui.mediaStarter.audio3.title": "Story passage read",
  "ui.mediaStarter.audio3.tag": "Speech",
  "ui.mediaStarter.audio3.prompt": "A 45-second cinematic read of an opening passage. Low, measured delivery with breath between sentences, slightly intimate close-mic'd quality. Script: 'The city sleeps in pieces. A neon sign flickers above the ramen counter. Across the avenue, a window glows — the only one still on this side of midnight.'",
